// The server's shapes, from its OpenAPI (schema.d.ts is generated by
// `npm run types`; never edited by hand). Where the server types a field as
// a free object (Dict[str, Any]) the narrower shape the web app reads is
// written here, next to the generated one, and named after the Python that
// makes it.
import type { components } from "./schema";

type Sch = components["schemas"];

export type Pt = [number, number];
export type Loop = Pt[];
export type Issue = Sch["IssueOut"];
export type Layer = Sch["LayerOut"];
export type MeshBody = Sch["MeshOut"];
export type Frames = Sch["FramesOut"];
export type Guides = Sch["GuidesOut"];
export type TargetIn = Sch["TargetIn"];
export type TagSpecIn = Sch["TagSpecIn"];

/** plan/mesh.top: {colour: [polygon = [outer loop, hole loops...]]} */
export type TopView = Partial<Record<"body" | "white" | "black", Loop[][]>>;

/** TagPlanOut plus the two optional extras the Studio asks for. */
export type TagPlan = Sch["TagPlanOut"] & { top?: TopView };

/** core.markers.TagSpec.to_dict() as built (TagPlan.marker). */
export interface MarkerAsBuilt {
  dictionary: string;
  marker_id: number;
  marker_length_m: number;
  layout: "single" | "grid" | "charuco";
  rows?: number;
  cols?: number;
  ids?: number[];
  square_length_m?: number;
  quiet_modules?: number;
  [k: string]: unknown;
}

/** A TagSpec as the scene keeps it (plan/spec.TagSpec.to_dict()). */
export interface TagSpec {
  schema: string;
  settings: Settings;
  numbers: Record<string, number>;
  target: Target;
  name: string;
  key: string;
}

export type Settings = Record<string, unknown> & {
  layout?: string;
  label?: Record<string, unknown>;
};

/** plan/target.Target.to_dict() (ARCHITECTURE 5.1, PLAN section 8). */
export interface Target {
  kind: string;
  w_mm: number;
  h_mm: number;
  loops_mm: Loop[];
  has_body: boolean;
  z_sign: number;
  x_ref: Pt | null;
  body_mm: { u0: number; v0: number; u1: number; v1: number; z0: number; z1: number; measured?: boolean; depth?: number } | null;
  body_loops_mm: Loop[] | null;
  face_loops_mm: Loop[] | null;
  name: string;
  [k: string]: unknown;
}

/** scene/model.SceneTag.to_dict() (ARCHITECTURE 5.5) with its plan. */
export interface SceneTag {
  name: string;
  uid: string;
  spec: TagSpec;
  x_mm: number;
  y_mm: number;
  rotation_deg: number;
  pose: number[];
  locked: boolean;
  hidden: boolean;
  plan: TagPlan | null;
}

export interface SceneDoc {
  schema: string;
  units: string;
  name: string;
  tags: SceneTag[];
  ledger: unknown;
  overrides: Record<string, number>;
  presets_used: string[];
}

/** plan/fields.py: one row of the inspector's contract (GET /api/form). */
export interface FormField {
  path: string;
  group: string;
  type: string;
  label: string;
  default: unknown;
  choices?: { value: string | number; label: string }[];
  min?: number;
  max?: number;
  min_exclusive?: number;
  min_abs?: number | null;
  warn_below?: number;
  layouts?: string[];
  read_only?: boolean;
  of?: string[];
  axes?: string[];
  min_mm?: number;
  max_mm?: number;
  min_cap?: number;
  [k: string]: unknown;
}

export interface FormDoc {
  schema: string;
  fields: FormField[];
  groups: string[];
  layouts: string[];
  rules: Record<string, number>;
}

export interface PaletteEntry {
  key: string;
  title: string;
  target: Target;
}

export interface Dictionary {
  name: string;
  bits: number;
  capacity: number;
  family: string;
  modules: number;
}

/** core.presets' preset shape (bam_aruco_presets/1). */
export interface Preset {
  name: string;
  profile: Record<string, unknown>;
  cells: Record<string, unknown>;
  tag: Record<string, unknown>;
  label: Record<string, unknown>;
}

export interface PresetItem {
  name: string;
  kind: "builtin" | "user";
  preset: Preset;
}

/** server/library.py's card (REF aruco_preset_library.Library._card). */
export interface LibraryCard {
  id: string;
  name: string;
  kind: "builtin" | "user" | "prusa" | "document";
  in: string[];
  editable: boolean;
  subtitle: string;
  nozzle?: number;
  line?: number;
  layer?: number | null;
  dictionary?: string;
  mode?: string;
  mode_words?: string;
  profile?: string;
  cells?: string;
  thumb: string;
  used: number;
  info: [string, [string, string][]][];
  recent: number | null;
  differs: string;
  preset: Preset | null;
  unreadable?: boolean;
}

export interface LibraryState {
  title: string;
  collections: { id: string; name: string; icon: string; count: number }[];
  cards: LibraryCard[];
  selected: string | null;
  schema: [string, string, string, [string, string][] | null][];
  notes: string[];
  dialog: boolean;
}

/** core.numbering's IdsPlan row (scene/ids.renumber). */
export interface RenumberRow {
  tag: string;
  name: string;
  final: number;
  ids?: number[];
  [k: string]: unknown;
}

export interface RenumberReport {
  rows: RenumberRow[];
  changed: { tag: string; from: number; to: number }[];
  duplicates: unknown;
  warnings: string[];
  errors: string[];
  ok: boolean;
}

/** verify/report.verify_plan. */
export interface VerifyReport {
  ok: boolean;
  errors?: string[];
  ids_expected: number[];
  ids_read: number[];
  missing?: number[];
  extra?: number[];
  corner_err_px?: number;
  corner_err_mm?: number;
  pnp_err_mm?: number;
  pnp_err_deg?: number;
  charuco_corners?: number;
  charuco_read?: number;
  image_png?: string;
  [k: string]: unknown;
}
